class Opt:
    def __init__(s, name, arg=None): s.name=name; s.option_arg=arg
class Inv:
    def __init__(s, fol, ops): s.flag_option_list=fol; s.operand_list=ops
class InputOutputInfoGeneratorInterface:
    def __init__(s, inv): s.cmd_inv=inv; s.log=[]
    def does_flag_option_list_contain_at_least_one_of(s, names): return any(o.name in names for o in s.cmd_inv.flag_option_list)
    def get_flag_option_list_filtered_with(s, names): return [o for o in s.cmd_inv.flag_option_list if o.name in names]
    def get_operand_list_length(s): return len(s.cmd_inv.operand_list)
    def get_first_operand_name_as_string(s): return s.cmd_inv.operand_list[0]
    def __getattr__(s, n):
        if n.startswith("set_") or n.startswith("all_") or n.startswith("only_") or n.startswith("if_"):
            return lambda *a: s.log.append(n)
        raise AttributeError(n)
