help_opts = set(re.findall(r"(?<![\w-])(--?[a-zA-Z][\w-]*)", help_txt.split("Mandatory")[1].split("GNU coreutils online")[0]))
help_opts -= {"-HI"}  # artefact of "LO-HI"
