    for node in s[0]:
        syn_opts.add(node.flag); syn_opts.update(node.alias)
# --- options in the json table
tbl_opts=set()
for e in tbl["flag"]: tbl_opts.update([e] if isinstance(e,str) else e)
for e in tbl["option"]: tbl_opts.update(x for x in e[:-1])
print("help - syntax:", help_opts-syn_opts); print("syntax - help:", syn_opts-help_opts)
print("help - json:", help_opts-tbl_opts); print("json - help:", tbl_opts-help_opts)

# --- does the binary accept each option exactly as classified (flag vs value)?
def run(args, stdin=""):
    r=subprocess.run(["/usr/bin/shuf"]+args,input=stdin,capture_output=True,text=True,timeout=5); return r.returncode, r.stderr.strip()
sample_val={"Integer":"1","Path":"/dev/urandom","Range":"1-3"}
for s in syn:
    for node in s[0]:
        for sp in [node.flag]+node.alias:
            if sp in ("--help","--version"): continue
            base = ["-i","1-3"] if node.flag!="-i" and node.flag!="-e" else []
            if node.flag=="-e": base=[]
            if node.kind=="Flag":
                rc,err=run(base+[sp]+(["-n","1"] if sp in("-r","--repeat") else []))
                assert rc==0,(sp,err)
                rc,err=run(base+[sp+"=x"]); assert rc!=0 or not sp.startswith("--"),(sp,"accepted a value?!")
            else:
                v=sample_val[node.kind]
                if node.flag=="-o": v="/tmp/shufcheck/o.txt"
