 "--echo -o out a": ["set_all_operands_as_config_arg_type_string"],
 "-i 1-3": ["set_implicit_use_of_stdout"],
 "--input-range 1-3 -n 1 -r": ["set_implicit_use_of_stdout"],
 "--random-source /dev/urandom -n 1 f1": ["all_operands_are_streaming_inputs","set_implicit_use_of_stdout"],
}
